from proto import *
def spir(a0, a1, r0, r1, step=3): return arcpts(lambda a: r0 + (r1-r0)*(a-a0)/(a1-a0), a0, a1, step)
def run(name, tail=[(0,-40,35,35)], horn=[(24.5,-29.5),(21.5,-27.2)], headE=[], headW=[], sl=[(-148,-174,30,30)], north=[P(35,-177)], endR=35, quiet=False):
    Hh = sum([spir(*t) for t in tail], []) + horn + headE + headW + sum([spir(*s) for s in sl], []) + north + [P(endR,-179.9)]
    F = evaluate(Hh, name); print('   ', deficit(F))
    print('     ', ' '.join(f"z{z}:{np.nonzero(F[z+90])[0].min()-60}..{np.nonzero(F[z+90])[0].max()-59}" for z in [-62,-55,-48,-41,-34,-27]))
    return F
E2 = [(12.7,-29.1),(6,-32),(1,-37),(-1.5,-44),(0,-51),(3,-56),(5,-61),(4,-66.5)]
W2 = [(-34,-66.5),(-38,-62),(-40.5,-55),(-41,-47),(-40.5,-39),(-38.5,-32),(-35.5,-26.5)]
run('c1', tail=[(0,-20,35,35),(-20,-40,35,30)], horn=[(25,-24),(24,-28.5),(21.5,-27.2)], headE=E2, headW=W2)
run('c2', tail=[(0,-20,36,36),(-20,-40,36,30)], horn=[(25,-24),(24,-28.5),(21.5,-27.2)], headE=E2, headW=W2, sl=[(-148,-174,28,28)], north=[P(38,-177)], endR=36)
run('c3', tail=[(0,-20,36,36),(-20,-40,36,30)], horn=[(25,-24),(24,-28.5),(21.5,-27.2)], headE=E2, headW=[(-34,-66.5),(-38,-62),(-40.5,-55),(-41,-47),(-41,-39),(-40,-33),(-37,-29)], sl=[(-146,-150,40,28),(-150,-174,28,28)], north=[P(38,-177)], endR=36)
